<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>City Skyline Day‑Night Cycle</title>
<style>
  body,html{margin:0;padding:0;overflow:hidden;background:#000;}
  canvas{display:block;}
</style>
</head>
<body>
<canvas id="sky"></canvas>
<script>
const canvas = document.getElementById('sky');
const ctx = canvas.getContext('2d');
let W, H;

// Resize handling
function resize(){
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
window.addEventListener('resize',resize);
resize();

// ------- Skyline data -------
const buildingCount = 12;
const buildings = [];
for(let i=0;i<buildingCount;i++){
  const bw = Math.random()*80+60;
  const bh = Math.random()*H*0.4+H*0.2;
  const bx = i*(W/buildingCount)+Math.random()*20;
  const by = H-bh;
  // windows grid
  const winW = 8, winH = 12, winGapX = 4, winGapY = 6;
  const cols = Math.floor((bw-10)/(winW+winGapX));
  const rows = Math.floor((bh-20)/(winH+winGapY));
  const windows=[];
  for(let r=0;r<rows;r++){
    for(let c=0;c<cols;c++){
      windows.push({x:10+c*(winW+winGapX), y:10+r*(winH+winGapY), lit:false});
    }
  }
  buildings.push({x:bx, y:by, w:bw, h:bh, windows});
}

// ------- Stars -------
const stars = [];
for(let i=0;i<200;i++){
  stars.push({x:Math.random()*W, y:Math.random()*H*0.6, r:Math.random()*1.5+0.5});
}

// Cycle timing
const CYCLE = 10000; // ms

function lerp(a,b,t){return a+(b-a)*t;}
function lerpColor(c1,c2,t){
  const r=lerp(c1[0],c2[0],t);
  const g=lerp(c1[1],c2[1],t);
  const b=lerp(c1[2],c2[2],t);
  return `rgb(${r|0},${g|0},${b|0})`;
}

// Main draw
let lastPhase = null;
function draw(timestamp){
  const t = timestamp % CYCLE;
  const phase = t / CYCLE; // 0‑1

  // ---------- Sky ----------
  const dayColor = [135,206,235];   // light sky blue
  const nightColor = [10,10,55];    // dark blue
  const skyColor = lerpColor(dayColor, nightColor,
        Math.cos(phase*2*Math.PI)*0.5+0.5); // smooth transition
  ctx.fillStyle = skyColor;
  ctx.fillRect(0,0,W,H);

  // ---------- Stars ----------
  const isNight = phase>0.75 || phase<0.25;
  if(isNight){
    ctx.fillStyle = 'white';
    stars.forEach(s=>{ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,2*Math.PI);ctx.fill();});
  }

  // ---------- Sun / Moon ----------
  const angle = phase*2*Math.PI - Math.PI/2; // start at left horizon
  const radius = Math.min(W,H)/2.5;
  const cx = W/2, cy = H*0.75;
  const sx = cx + radius*Math.cos(angle);
  const sy = cy + radius*Math.sin(angle);
  if(!isNight){
    // Sun
    const grad = ctx.createRadialGradient(sx,sy,5,sx,sy,30);
    grad.addColorStop(0,'rgba(255,255,200,0.9)');
    grad.addColorStop(1,'rgba(255,200,0,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();ctx.arc(sx,sy,30,0,2*Math.PI);ctx.fill();
  }else{
    // Moon
    ctx.fillStyle = 'rgba(250,250,250,0.8)';
    ctx.beginPath();ctx.arc(sx,sy,22,0,2*Math.PI);ctx.fill();
    // simple crescent cut
    ctx.fillStyle = skyColor;
    ctx.beginPath();ctx.arc(sx+8,sy-5,20,0,2*Math.PI);ctx.fill();
  }

  // ---------- Buildings ----------
  ctx.fillStyle = '#222';
  buildings.forEach(b=>{
    ctx.fillRect(b.x,b.y,b.w,b.h);
    // windows lighting
    if(isNight){
      // generate new pattern once per night start
      if(lastPhase===null || (lastPhase<0.25 && phase>=0.25) || (lastPhase>0.75 && phase<=0.75)){
        b.windows.forEach(w=> w.lit = Math.random()<0.6);
      }
      ctx.fillStyle = 'rgba(255,230,180,0.8)';
      b.windows.forEach(w=>{
        if(w.lit){
          ctx.fillRect(b.x+w.x, b.y+w.y, 8,12);
        }
      });
    }else{
      // day: no lit windows
    }
  });

  lastPhase = phase;
  requestAnimationFrame(draw);
}
requestAnimationFrame(draw);
</script>
</body>
</html>
```
The script continuously animates a 10‑second loop where the sky colour, sun/moon positions, stars, and building window lights transition smoothly to simulate a full day‑night cycle.
